import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadPointCalimereData(){const e=readFileSync(resolve(__dirname,"../../frontend/point-calimere-wetland-explorer/point-calimere-data.js"),"utf-8");return new Function(e+"\nreturn { POINT_CALIMERE_INFO, COASTAL_ECOLOGY, BIRD_MIGRATION, WILDLIFE_SPECIES, INTERESTING_FACTS, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Point Calimere Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadPointCalimereData()}),describe("POINT_CALIMERE_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.POINT_CALIMERE_INFO.id).toBe("point-calimere"),expect(e.POINT_CALIMERE_INFO.name).toContain("Point Calimere"),expect(e.POINT_CALIMERE_INFO.ramsarYear).toBe(2002),expect(e.POINT_CALIMERE_INFO.ramsarSiteNo).toBe(1210),expect(e.POINT_CALIMERE_INFO.state).toBe("Tamil Nadu")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.POINT_CALIMERE_INFO.quickStats)).toBe(!0),expect(e.POINT_CALIMERE_INFO.quickStats.length).toBe(6)})}),describe("COASTAL_ECOLOGY & BIRD_MIGRATION",()=>{it("contains overview, coastal habitats, mangroves, migration, and conservation status",()=>{expect(e.COASTAL_ECOLOGY.overview).toBeDefined(),expect(e.COASTAL_ECOLOGY.coastalHabitats).toBeDefined(),expect(e.COASTAL_ECOLOGY.mangroves).toBeDefined(),expect(e.COASTAL_ECOLOGY.birdMigration).toBeDefined(),expect(e.COASTAL_ECOLOGY.conservationStatus).toBeDefined()}),it("contains bird migration cards describing the Central Asian Flyway",()=>{expect(Array.isArray(e.BIRD_MIGRATION)).toBe(!0),expect(e.BIRD_MIGRATION.length).toBeGreaterThanOrEqual(4),expect(e.BIRD_MIGRATION.some(e=>e.title.includes("Central Asian Flyway"))).toBe(!0)})}),describe("WILDLIFE_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.WILDLIFE_SPECIES)).toBe(!0),expect(e.WILDLIFE_SPECIES.length).toBeGreaterThanOrEqual(6)}),it("includes Greater Flamingo, Lesser Flamingo and Blackbuck",()=>{const t=e.WILDLIFE_SPECIES.find(e=>"greater-flamingo"===e.id),a=e.WILDLIFE_SPECIES.find(e=>"lesser-flamingo"===e.id),i=e.WILDLIFE_SPECIES.find(e=>"blackbuck"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(i).toBeDefined()})}),describe("INTERESTING_FACTS",()=>{it("contains interesting facts array with at least 3 items",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(3)})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"point-calimere"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../point-calimere-wetland-explorer/index.html")})})});